@@ -46,6 +72,100 @@ export const getRunPodApiId = (baseModel: string) => {
   }
 };

+/**
+ * Get custom workflow JSON from the database for a given base model and generation mode.
+ * Returns null if no custom workflow is configured.
+ */
+export const getCustomWorkflow = async (
+  baseModel: string,
+  mode: ImageGenerationMode
+): Promise<JsonValue | null> => {
+  try {
+    const model = await getBaseModelByFileName(baseModel);
+    if (!model) return null;
+
+    switch (mode) {
+      case ImageGenerationMode.t2i:
+        return model.workflowT2i;
+      case ImageGenerationMode.i2i:
+        return model.workflowI2i;
+      default:
+        return null;
+    }
+  } catch (error) {
+    logger.warn('Failed to fetch custom workflow from database', {
+      baseModel,
+      mode,
+      error: error instanceof Error ? error.message : String(error)
+    });
+    return null;
+  }
+};
+
+/**
+ * Apply generation parameters to a custom workflow JSON.
+ * Finds nodes by class_type and updates their inputs with the provided parameters.
+ */
+export const applyParametersToWorkflow = (
+  workflow: JsonValue,
+  params: ImageGenerationData
+): Record<string, unknown> => {
+  // Deep clone the workflow
+  const result = JSON.parse(JSON.stringify(workflow)) as Record<
+    string,
+    {
+      inputs: Record<string, unknown>;
+      class_type: string;
+      _meta?: { title: string };
+    }
+  >;
+
+  // Apply common parameters by finding nodes with specific class_types
+  for (const nodeId in result) {
+    const node = result[nodeId];
+    if (!node || !node.class_type) continue;
+
+    // KSampler nodes - apply sampling parameters
+    if (
+      node.class_type === 'KSampler' ||
+      node.class_type === 'SamplerCustomAdvanced'
+    ) {
+      if (params.seed !== undefined) node.inputs.seed = params.seed;
+      if (params.steps !== undefined) node.inputs.steps = params.steps;
+      if (params.cfgScale !== undefined) node.inputs.cfg = params.cfgScale;
+      if (params.samplerName !== undefined)
+        node.inputs.sampler_name = params.samplerName;
+      if (params.scheduler !== undefined)
+        node.inputs.scheduler = params.scheduler;
+      if (params.denoisingStrength !== undefined)
+        node.inputs.denoise = params.denoisingStrength;
+    }
+
+    // CLIPTextEncode nodes - apply prompts based on title
+    if (node.class_type === 'CLIPTextEncode') {
+      const title = node._meta?.title?.toLowerCase() || '';
+      if (title.includes('positive') && params.prompt) {
+        node.inputs.text = params.prompt;
+      }
+      if (title.includes('negative') && params.negativePrompt) {
+        node.inputs.text = params.negativePrompt;
+      }
+    }
+
+    // EmptyLatentImage nodes - apply dimensions
+    if (
+      node.class_type === 'EmptyLatentImage' ||
+      node.class_type === 'EmptySD3LatentImage'
+    ) {
+      if (params.width) node.inputs.width = params.width;
+      if (params.height) node.inputs.height = params.height;
+      if (params.batchSize) node.inputs.batch_size = params.batchSize;
+    }
+  }
+
+  return result;
+};
+
 type ComfyUIRequestPayload = {
   workflow: Record<string, unknown> | string;
   images?: {
