+import { describe, it, expect } from 'vitest';
+
+import type { ImageOutput, ImageOutputObject } from '@/lib/comfyui/types';
+
+describe('ComfyUI Types', () => {
+  describe('ImageOutput', () => {
+    it('should accept base64 string format', () => {
+      const base64Image: ImageOutput = 'iVBORw0KGgoAAAANSUhEUgAAAAE...';
+      expect(typeof base64Image).toBe('string');
+    });
+
+    it('should accept obj_key/url object format', () => {
+      const objKeyImage: ImageOutput = {
+        obj_key:
+          'runpod-temp/4da89c08-7045-4e25-8ebd-62c8dfabd9b6-e1/9b9ad0c4.png',
+        url: 'https://d9f8def9zcjx0.cloudfront.net/runpod-temp/4da89c08-7045-4e25-8ebd-62c8dfabd9b6-e1/9b9ad0c4.png'
+      };
+      expect(typeof objKeyImage).toBe('object');
+      expect(objKeyImage).toHaveProperty('obj_key');
+      expect(objKeyImage).toHaveProperty('url');
+    });
+
+    it('should accept obj_key object without url (url is optional)', () => {
+      const objKeyOnly: ImageOutputObject = {
+        obj_key: 'runpod-temp/uuid/image.png'
+      };
+      expect(objKeyOnly.obj_key).toBe('runpod-temp/uuid/image.png');
+      expect(objKeyOnly.url).toBeUndefined();
+    });
+  });
+
+  describe('ImageOutput type guard examples', () => {
+    it('should distinguish between string and object formats', () => {
+      const images: ImageOutput[] = [
+        'base64string',
+        { obj_key: 'path/to/image.png', url: 'https://example.com/image.png' }
+      ];
+
+      const results = images.map((img) => {
+        if (typeof img === 'string') {
+          return { type: 'base64', value: img };
+        }
+        return { type: 'obj_key', value: img.obj_key, url: img.url };
+      });
+
+      expect(results[0]).toEqual({ type: 'base64', value: 'base64string' });
+      expect(results[1]).toEqual({
+        type: 'obj_key',
+        value: 'path/to/image.png',
+        url: 'https://example.com/image.png'
+      });
+    });
+  });
+});
