+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+import { getImageDimensionsFromBase64 } from '@/utils/client/image';
+
+describe('getImageDimensionsFromBase64', () => {
+  let originalImage: typeof Image;
+
+  beforeEach(() => {
+    // Save original Image constructor
+    originalImage = global.Image;
+    // Mock window for browser environment
+    vi.stubGlobal('window', {});
+  });
+
+  afterEach(() => {
+    // Restore original Image constructor
+    global.Image = originalImage;
+    vi.unstubAllGlobals();
+  });
+
+  describe('URL type detection', () => {
+    it('should handle HTTP URLs directly without prepending data URL prefix', async () => {
+      const httpUrl = 'http://example.com/image.png';
+      let capturedSrc = '';
+
+      // Mock Image constructor
+      class MockImage {
+        width = 100;
+        height = 200;
+        onload: (() => void) | null = null;
+        onerror: ((error: unknown) => void) | null = null;
+        set src(value: string) {
+          capturedSrc = value;
+          setTimeout(() => this.onload?.(), 0);
+        }
+      }
+      global.Image = MockImage as unknown as typeof Image;
+
+      const promise = getImageDimensionsFromBase64(httpUrl);
+      await expect(promise).resolves.toEqual({ width: 100, height: 200 });
+      expect(capturedSrc).toBe(httpUrl);
+    });
+
+    it('should handle HTTPS URLs directly without prepending data URL prefix', async () => {
+      const httpsUrl = 'https://cloudfront.example.com/assets/image.png';
+      let capturedSrc = '';
+
+      class MockImage {
+        width = 800;
+        height = 600;
+        onload: (() => void) | null = null;
+        onerror: ((error: unknown) => void) | null = null;
+        set src(value: string) {
+          capturedSrc = value;
+          setTimeout(() => this.onload?.(), 0);
+        }
+      }
+      global.Image = MockImage as unknown as typeof Image;
+
+      const promise = getImageDimensionsFromBase64(httpsUrl);
+      await expect(promise).resolves.toEqual({ width: 800, height: 600 });
+      expect(capturedSrc).toBe(httpsUrl);
+    });
+
+    it('should handle data URLs directly', async () => {
+      const dataUrl =
+        'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
+      let capturedSrc = '';
+
+      class MockImage {
+        width = 1;
+        height = 1;
+        onload: (() => void) | null = null;
+        onerror: ((error: unknown) => void) | null = null;
+        set src(value: string) {
+          capturedSrc = value;
+          setTimeout(() => this.onload?.(), 0);
+        }
+      }
+      global.Image = MockImage as unknown as typeof Image;
+
+      const promise = getImageDimensionsFromBase64(dataUrl);
+      await expect(promise).resolves.toEqual({ width: 1, height: 1 });
+      expect(capturedSrc).toBe(dataUrl);
+    });
+
+    it('should prepend data URL prefix for raw base64 strings', async () => {
+      const rawBase64 =
+        'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
+      let capturedSrc = '';
+
+      class MockImage {
+        width = 1;
+        height = 1;
+        onload: (() => void) | null = null;
+        onerror: ((error: unknown) => void) | null = null;
+        set src(value: string) {
+          capturedSrc = value;
+          setTimeout(() => this.onload?.(), 0);
+        }
+      }
+      global.Image = MockImage as unknown as typeof Image;
+
+      const promise = getImageDimensionsFromBase64(rawBase64);
+      await expect(promise).resolves.toEqual({ width: 1, height: 1 });
+      expect(capturedSrc).toBe(`data:image/png;base64,${rawBase64}`);
+    });
+  });
+
+  describe('error handling', () => {
+    it('should reject when used server-side (no window)', async () => {
+      vi.stubGlobal('window', undefined);
+
+      await expect(getImageDimensionsFromBase64('test')).rejects.toThrow(
+        'client-side only'
+      );
+    });
+
+    it('should reject when image fails to load', async () => {
+      vi.stubGlobal('window', {});
+
