+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+import { getImageDimensionsFromBase64 } from '@/utils/client/image';
+
+describe('getImageDimensionsFromBase64', () => {
+  let originalImage: typeof Image;
+
+  beforeEach(() => {
+    // Save original Image constructor
+    originalImage = global.Image;
+    // Mock window for browser environment
+    vi.stubGlobal('window', {});
+  });
+
+  afterEach(() => {
+    // Restore original Image constructor
+    global.Image = originalImage;
+    vi.unstubAllGlobals();
+  });
+
+  describe('URL type detection', () => {
+    it('should handle HTTP URLs directly without prepending data URL prefix', async () => {
+      const httpUrl = 'http://example.com/image.png';
+      let capturedSrc = '';
+
+      // Mock Image constructor
+      class MockImage {
+        width = 100;
+        height = 200;
+        onload: (() => void) | null = null;
+        onerror: ((error: unknown) => void) | null = null;
+        set src(value: string) {
+          capturedSrc = value;
+          setTimeout(() => this.onload?.(), 0);
+        }
+      }
+      global.Image = MockImage as unknown as typeof Image;
+
+      const promise = getImageDimensionsFromBase64(httpUrl);
+      await expect(promise).resolves.toEqual({ width: 100, height: 200 });
+      expect(capturedSrc).toBe(httpUrl);
+    });
+
+    it('should handle HTTPS URLs directly without prepending data URL prefix', async () => {
